import{_ as s,a2 as l,o,c as i,C as t,a as r,J as d,K as p,au as n}from"./chunks/framework.DCarWLHJ.js";const v=JSON.parse('{"title":"性能与容量说明","description":"","frontmatter":{"date":"2026-08-18T22:23:17.000Z","title":"性能与容量说明","encrypt":false,"permalink":"/performance/"},"headers":[],"relativePath":"05.性能与容量说明.md","filePath":"zh/05.性能与容量说明.md","lastUpdated":1787074097000}'),m=s({name:"05.性能与容量说明.md"},[["render",function(h,a,c,q,g,u){const e=l("VPNolebaseInlineLinkPreview");return o(),i("div",null,[a[2]||(a[2]=t("h1",{id:"性能与容量说明",tabindex:"-1"},[r("性能与容量说明 "),t("a",{class:"header-anchor",href:"#性能与容量说明","aria-label":'Permalink to "性能与容量说明"'},"​")],-1)),a[3]||(a[3]=t("h2",{id:"压测工具",tabindex:"-1"},[r("压测工具 "),t("a",{class:"header-anchor",href:"#压测工具","aria-label":'Permalink to "压测工具"'},"​")],-1)),a[4]||(a[4]=t("p",null,"主要使用 goose 压测。",-1)),t("p",null,[a[1]||(a[1]=r("参考项目中的子工程 ",-1)),d(e,{href:"https://github.com/heqingpan/rnacos/tree/master/loadtest",target:"_blank",rel:"noreferrer"},{default:p(()=>[...a[0]||(a[0]=[r("loadtest",-1)])]),_:1})]),a[5]||(a[5]=n('<h2 id="性能压测结果" tabindex="-1">性能压测结果 <a class="header-anchor" href="#性能压测结果" aria-label="Permalink to &quot;性能压测结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>场景</th><th>单节点 qps/tps</th><th>集群 qps/tps</th><th>总结/备注</th></tr></thead><tbody><tr><td>配置中心</td><td>配置写入，http 协议</td><td>1.76 万</td><td>7.6 千</td><td>集群写入压测是在同一台电脑运行 3 个节点，如果换成多个机器部署，tps 应该还能有所提升。</td></tr><tr><td>配置中心</td><td>配置查询，http 协议</td><td>8 万</td><td>n*8 万</td><td>集群的查询总 qps 是节点的倍数</td></tr><tr><td>注册中心</td><td>服务实例注册，http 协议</td><td>4.8 万</td><td>2.4 万</td><td>集群写入压测是在同一台电脑运行 3 个节点，如果换成多个机器部署，tps 应该还能有所提升。</td></tr><tr><td>注册中心</td><td>服务实例注册，grpc 协议</td><td>4.8 万</td><td>2.4 万</td><td>grpc 协议压测工具没有支持，目前没有实际压测，理论不会比 http 协议低</td></tr><tr><td>注册中心</td><td>服务实例心跳，http 协议</td><td>4.8 万</td><td>2.4 万</td><td>心跳是按实例计算和服务实例注册一致共享 qps</td></tr><tr><td>注册中心</td><td>服务实例心跳，grpc 协议</td><td>8 万以上</td><td>n*8 万</td><td>心跳是按请求链接计算，且不过注册中心处理线程，每个节点只需管理当前节点的心跳，集群总心跳 qps 是节点的倍数</td></tr><tr><td>注册中心</td><td>查询服务实例</td><td>5.4 万</td><td>n*5.4 万</td><td>集群的查询总 qps 是节点的倍数</td></tr></tbody></table><p><strong>注：</strong> 具体结果和压测环境有关</p><h3 id="压测记录" tabindex="-1">压测记录 <a class="header-anchor" href="#压测记录" aria-label="Permalink to &quot;压测记录&quot;">​</a></h3><p>注册中心查询：</p><figure><img src="https://github.com/heqingpan/rnacos/raw/master/doc/assets/imgs/20230903202816.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>配置中心查询，两个进程分别限流 4 万 qps 同时压测 (共 8 万 qps)，其中一个的压测记录：</p><figure><img src="https://github.com/heqingpan/rnacos/raw/master/doc/assets/imgs/20230903205737.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="容量分析" tabindex="-1">容量分析 <a class="header-anchor" href="#容量分析" aria-label="Permalink to &quot;容量分析&quot;">​</a></h2><h3 id="配置中心" tabindex="-1">配置中心 <a class="header-anchor" href="#配置中心" aria-label="Permalink to &quot;配置中心&quot;">​</a></h3><ol><li>配置中心的单机查询 8 万 qps，很高，又支持水平扩容；集群基本没有查询瓶颈。</li><li>配置中心所占用的内存和配置内存有关，在内存没有满前，基本没有瓶颈。</li><li>配置中心集群写入时统一在主节点写入，写入可能有瓶颈；目前 1.5 千 tps，后面优化后应该能到 1 万 tps 以上。</li></ol><h3 id="注册中心" tabindex="-1">注册中心 <a class="header-anchor" href="#注册中心" aria-label="Permalink to &quot;注册中心&quot;">​</a></h3><ol><li>注册中心的单机查询 3 万 qps，比较高，又支持水平扩容；集群基本没有查询瓶颈。</li><li>注册中心所占用的内存和配置内存有关，在内存没有满前，基本没有瓶颈。</li><li>注册中心集群写入时每个节点都要写一遍，整体集群的写入性能 tps 和单机理论上相当。</li><li>http 协议 (v1.x 版本) 和 grpc 协议 (v2.x) 的心跳维护机制不同；http 心跳是按实例计算和服务实例注册一致共享 qps, grpc 的心跳是按请求链接计算且不过注册中心处理线程。所有这类协议理论支持的容量差别很大。</li></ol><h4 id="注册中心集群注册容量推理" tabindex="-1">注册中心集群注册容量推理 <a class="header-anchor" href="#注册中心集群注册容量推理" aria-label="Permalink to &quot;注册中心集群注册容量推理&quot;">​</a></h4><ol><li>http 协议注册 + 心跳 qps 是 1 万，每个实例 5 秒钟一次心跳；理论上只能支持 5 万服务实例左右。</li><li>grpc 协议，注册 qps 假设也是 1 万，心跳 qps 单实例 8 万，3 节点集群总心跳 24 万；如果平均一个应用实例 1 小时重连一次；支持注册的服务实例总数为：60<em>60</em>10000 = 3600 万，心跳支持的链接实例总数为：5*24 万=120 万个链接实例（和集群节点有关）。</li></ol><p>结论： 如果使用 v1.0x http 协议，支持的实例在 5 万个左右。 如果使用 v2.0x grpc 协议，理论上基本没有瓶颈。</p><hr><h2 id="r-nacos-与-java-nacos-性能压测对比-单机模式" tabindex="-1">r-nacos 与 java nacos 性能压测对比（单机模式） <a class="header-anchor" href="#r-nacos-与-java-nacos-性能压测对比-单机模式" aria-label="Permalink to &quot;r-nacos 与 java nacos 性能压测对比（单机模式）&quot;">​</a></h2><p>旧版本的单机压测记录，有和 java 版本 nacos 的比较。</p><h3 id="压测环境与工具" tabindex="-1">压测环境与工具 <a class="header-anchor" href="#压测环境与工具" aria-label="Permalink to &quot;压测环境与工具&quot;">​</a></h3><p>压测环境:macos i7 四核 /16G，施压、受压机器是同一台机器（会拉低压测结果）。 压测工具： * wrk ,qps: 24450 左右 * goose, qps 17000 左右（单进程加限流施压比 wrk 低） * 单进程施压请求 wrk 比 goose 输出高</p><p>r-nacos server 版本：v0.1.1 java nacos server 版本：2.1.0</p><p><strong>因 wrk,goose 暂时不支持 grpc 协议，暂时只压测 http 协议接口</strong></p><h3 id="配置中心-1" tabindex="-1">配置中心 <a class="header-anchor" href="#配置中心-1" aria-label="Permalink to &quot;配置中心&quot;">​</a></h3><p>配置中心，不会频繁更新，写入不做压测。</p><h4 id="rust-r-nacos-server" tabindex="-1">rust r-nacos server: <a class="header-anchor" href="#rust-r-nacos-server" aria-label="Permalink to &quot;rust r-nacos server:&quot;">​</a></h4><ol><li>配置中心单机查询 wrk 压测 qps 在 2.4 万左右。</li></ol><h4 id="java-nacos-server" tabindex="-1">java nacos server: <a class="header-anchor" href="#java-nacos-server" aria-label="Permalink to &quot;java nacos server:&quot;">​</a></h4><ol><li>配置中心单机查询 wrk 压测，qps 在 7700 左右</li></ol><h3 id="注册中心-1" tabindex="-1">注册中心 <a class="header-anchor" href="#注册中心-1" aria-label="Permalink to &quot;注册中心&quot;">​</a></h3><h4 id="rust-r-nacos-server-1" tabindex="-1">rust r-nacos server: <a class="header-anchor" href="#rust-r-nacos-server-1" aria-label="Permalink to &quot;rust r-nacos server:&quot;">​</a></h4><ol start="2"><li>naming 注册 1000 x 1 个实例，每秒 200qps，单核 cpu: 4.5% 左右</li><li>naming 单查询 1.5 万 QPS 左右 <ol><li>wrk 查询单个服务，1.65 万 qps</li><li>goose 查询 1000 个服务，1.5 万 qps</li></ol></li><li>naming 单注册服务 <ol><li>goose,5 万到 7 万实例数 0.7 万 qps 左右。</li></ol></li><li>查询与注册混合 <ol><li>wrk 查询单个服务（1.5 万 qps) + goose 注册（0.075 万 qps) 【5 千实例】</li><li>goose 查询 1000 个服务（1.3 万 qps) + goose 注册（0.07 万 qps) 【5 千实例】</li><li>wrk 查询单个服务（1.5 万 qps) + goose 注册（0.15 万 qps) 【1 万实例】</li><li>goose 查询 1000 个服务（1.3 万 qps) + goose 注册（0.13 万 qps) 【1 万实例】</li></ol></li></ol><h4 id="java-nacos-server-1" tabindex="-1">java nacos server: <a class="header-anchor" href="#java-nacos-server-1" aria-label="Permalink to &quot;java nacos server:&quot;">​</a></h4><ol><li>配置中心查询 wrk 压测，7700 qps 左右</li><li>naming 注册 1000 x 1 个实例，每秒 200qps，单核 cpu: 17% 左右</li><li>naming 单查询 <ol><li>wrk 查询单个服务，1.35 万 qps。</li><li>goose 查询 1000 个服务，1 万 qps（前期应该还能上去一些）。前 30 秒能稳定在 1 万左右，30 秒后，跌到 200 左右之后再上下浮动，可能受 GC 影响。</li></ol></li><li>naming 单注册 <ol><li>goose,5 万到 7 万实例数 0.45 万 qps 左右。</li></ol></li><li>查询与注册混合 <ol><li>wrk 查询单个服务（1.3 万 qps) + goose 注册（0.07 万 qps) 【5 千实例】</li><li>goose 查询 1000 个服务（1 万 qps) + goose 注册（0.07 万 qps) 【5 千实例】; 前期能保持，后期 qps 上下浮动比较大，最低小于 50。</li><li>wrk 查询单个服务（0.9 万 qps) + goose 注册（0.12 万 qps) 【1 万实例】</li><li>goose 查询 1000 个服务（0.6 万 qps) + goose 注册（0.08 万 qps) 【1 万实例】</li></ol></li></ol><h3 id="性能压测总结" tabindex="-1">性能压测总结 <a class="header-anchor" href="#性能压测总结" aria-label="Permalink to &quot;性能压测总结&quot;">​</a></h3><ol><li><p>r-nacos，除了服务服务注册不能稳定在 1 万以上，其它的接口 qps 都能稳定在 1 万以上。</p></li><li><p>java 的查询接口基本能压到 1 万以上，但不平稳，后继浮动比较大。如果降低压测流程，qps 可以相对平稳。</p></li><li><p>在多服务查询叠加上多服务注册场景，r-nacos qps 能稳定在 1.3 万左右，java nacos qps 下降明显在 0.6 万左右。</p></li><li><p>r-nacos 综合 qps 是 java 版的 2 倍以上，因 java 有 GC，qps 水位稳定性上 java 较差（相同施压流量，qps 能从峰值 1 万能降到 1 百以下）。</p></li><li><p>r-nacos 服务，线程数稳定在 7，cpu 用例率最大 200% 左右（相当用个 2 核），内存在 50M 以下</p></li><li><p>java nacos 服务，线程数最大 300 左右，cpu 用例率最大 500% 左右，内存 600M 到 900M。</p></li></ol>',36))])}]]);export{v as __pageData,m as default};
